50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import tools.jackson.databind.ObjectMapper;
57	
58	import jakarta.servlet.http.HttpServletRequest;
59	import jakarta.transaction.Transactional;
