61	/**
62	 * @author Vitaliy Fedoriv
63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
71	
72	    /** Emits the welcome notification enqueued for each newly created owner. */
73	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
74	
75	    /** Source of the monotonically increasing {@code seq} carried by each {@link OwnerCreatedAuditEvent}. */
76	    private static final AtomicLong AUDIT_SEQ = new AtomicLong();
77	
78	    private final ClinicService clinicService;
79	
80	    private final OwnerMapper ownerMapper;
81	
82	    private final PetMapper petMapper;
83	
84	    private final VisitMapper visitMapper;
85	
86	    private final IdempotencyStore idempotencyStore;
87	
88	    private final HttpServletRequest request;
89	
90	    private final ObjectMapper objectMapper;
91	
92	    public OwnerRestControllerV1(ClinicService clinicService,
93	                                 OwnerMapper ownerMapper,
94	                                 PetMapper petMapper,
95	                                 VisitMapper visitMapper,
96	                                 IdempotencyStore idempotencyStore,
97	                                 HttpServletRequest request,
98	                                 ObjectMapper objectMapper) {
99	        this.clinicService = clinicService;
100	        this.ownerMapper = ownerMapper;
101	        this.petMapper = petMapper;
102	        this.visitMapper = visitMapper;
103	        this.idempotencyStore = idempotencyStore;
104	        this.request = request;
105	        this.objectMapper = objectMapper;
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
111	        Collection<Owner> owners;
112	        if (lastName != null) {
113	            owners = this.clinicService.findOwnerByLastName(lastName);
114	        } else {
115	            owners = this.clinicService.findAllOwners();
116	        }
117	        if (owners.isEmpty()) {
118	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
119	        }
120	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
126	        Owner owner = this.clinicService.findOwnerById(ownerId);
127	        if (owner == null) {
128	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
129	        }
130	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
136	        String idempotencyKey = request.getHeader("Idempotency-Key");
137	        ResponseEntity<OwnerDto> replayed = replayIdempotent(idempotencyKey);
138	        if (replayed != null) {
139	            return replayed;
140	        }
141	        HttpHeaders headers = new HttpHeaders();
142	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
143	        String telephone = TelephoneNormalizer.normalize(owner.getTelephone());
144	        owner.setTelephone(telephone);
145	        String email = EmailNormalizer.normalize(owner.getEmail());
146	        owner.setEmail(email);
147	        normalizeAddress(owner);
148	        PostcodeValidator.validate(owner.getPostcode(), owner.getCity());
149	        RegistrationDateValidator.validate(owner.getRegistrationDate());
150	        LocalDate effectiveRegistrationDate =
151	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
152	        owner.setRegistrationDate(RegistrationDateNormalizer.normalize(effectiveRegistrationDate));
153	        this.clinicService.createOwner(owner);
154	        Integer membershipLevel = ownerMapper.membershipLevel(owner);
155	        AUDIT.info("owner created: id={} memberId={} registrationDate={} membershipLevel={}",
156	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), membershipLevel);
157	        OwnerCreatedAuditEvent event = new OwnerCreatedAuditEvent(AUDIT_SEQ.incrementAndGet(),
158	            owner.getId(), owner.getMemberId(), membershipLevel);
159	        AUDIT.info(objectMapper.writeValueAsString(event));
160	        NOTIFY.info("welcome notification enqueued: id={} memberId={}",
161	            owner.getId(), owner.getMemberId());
162	        idempotencyStore.remember(idempotencyKey, owner.getId());
163	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
164	        headers.setLocation(UriComponentsBuilder.newInstance()
165	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
166	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
167	    }
168	
169	    /**
170	     * When {@code idempotencyKey} names a create that already succeeded, return the originally
171	     * created owner with {@code 200 OK} so the repeat is not persisted as a duplicate. Returns
172	     * {@code null} when there is no key or none has been seen, so the caller proceeds with a
173	     * normal create.
174	     */
175	    private ResponseEntity<OwnerDto> replayIdempotent(String idempotencyKey) {
176	        return idempotencyStore.find(idempotencyKey)
177	            .map(this.clinicService::findOwnerById)
178	            .map(owner -> new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK))
179	            .orElse(null);
180	    }
181	
182	    /**
183	     * Normalizes the owner's address, preferring the structured form. When a non-blank
184	     * {@code addressLine1} is supplied, both structured lines are normalized and the flat
185	     * {@code address} is composed from them: the normalized {@code addressLine1}, and — when
186	     * {@code addressLine2} is present — a single space followed by the normalized
187	     * {@code addressLine2}. Otherwise the flat {@code address} is normalized on its own,
188	     * preserving backward compatibility. Either way a blank address is rejected with a
189	     * {@code 400 Bad Request} by {@link AddressNormalizer#normalize(String)}.
190	     */
191	    private void normalizeAddress(Owner owner) {
192	        String addressLine1 = owner.getAddressLine1();
193	        if (addressLine1 != null && !addressLine1.isBlank()) {
194	            String line1 = AddressNormalizer.normalize(addressLine1);
195	            owner.setAddressLine1(line1);
196	            String addressLine2 = owner.getAddressLine2();
197	            if (addressLine2 != null && !addressLine2.isBlank()) {
198	                String line2 = AddressNormalizer.normalize(addressLine2);
199	                owner.setAddressLine2(line2);
200	                owner.setAddress(line1 + " " + line2);
201	            } else {
202	                owner.setAddressLine2(null);
203	                owner.setAddress(line1);
204	            }
205	        } else {
206	            owner.setAddress(AddressNormalizer.normalize(owner.getAddress()));
207	        }
208	    }
209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Override
212	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
213	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
214	        if (currentOwner == null) {
215	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
216	        }
217	        currentOwner.setAddress(ownerFieldsDto.getAddress());
218	        currentOwner.setCity(ownerFieldsDto.getCity());
219	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
220	        currentOwner.setLastName(ownerFieldsDto.getLastName());
221	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
222	        currentOwner.setEmail(EmailNormalizer.normalize(ownerFieldsDto.getEmail()));
223	        this.clinicService.saveOwner(currentOwner);
224	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
225	    }
226	
227	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
228	    @Transactional
229	    @Override
230	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
231	        Owner owner = this.clinicService.findOwnerById(ownerId);
232	        if (owner == null) {
233	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
234	        }
235	        this.clinicService.deleteOwner(owner);
236	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
237	    }
238	
239	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
240	    @Override
241	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
242	        Owner owner = this.clinicService.findOwnerById(ownerId);
243	        if (owner == null) {
244	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
245	        }
246	        HttpHeaders headers = new HttpHeaders();
247	        Pet pet = petMapper.toPet(petFieldsDto);
248	        owner.setId(ownerId);
249	        pet.setOwner(owner);
250	        pet.getType().setName(null);
251	        this.clinicService.savePet(pet);
252	        PetDto petDto = petMapper.toPetDto(pet);
253	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
254	            .buildAndExpand(pet.getId()).toUri());
255	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
256	    }
257	
258	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
259	    @Override
260	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
261	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
262	        if (currentOwner != null) {
263	            Pet currentPet = this.clinicService.findPetById(petId);
264	            if (currentPet != null) {
265	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
266	                currentPet.setName(petFieldsDto.getName());
267	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
268	                this.clinicService.savePet(currentPet);
269	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
270	            }
271	        }
272	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
273	    }
274	
275	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
276	    @Override
277	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
278	        HttpHeaders headers = new HttpHeaders();
279	        Visit visit = visitMapper.toVisit(visitFieldsDto);
280	        Pet pet = new Pet();
281	        pet.setId(petId);
282	        visit.setPet(pet);
283	        this.clinicService.saveVisit(visit);
284	        VisitDto visitDto = visitMapper.toVisitDto(visit);
285	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
286	            .buildAndExpand(visit.getId()).toUri());
287	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
288	    }
289	
290	
291	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
292	    @Override
293	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
294	        Owner owner = this.clinicService.findOwnerById(ownerId);
295	        if (owner != null) {
296	            Pet pet = owner.getPet(petId);
297	            if (pet != null) {
298	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
299	            }
300	        }
301	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
302	    }
303	}
