58	        if (owner == null) {
59	            return null;
60	        }
61	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
62	        String firstName = owner.getFirstName() == null ? "" : owner.getFirstName();
63	        return lastName + ", " + firstName;
