66	    /**
67	     * Composes the owner's salutation as {@code '<title> <lastName>'} — the title, a single
68	     * space and the last name — or just the last name when no (blank/absent) title is given.
69	     */
70	    default String salutation(Owner owner) {
71	        if (owner == null) {
72	            return null;
73	        }
74	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
75	        String title = owner.getTitle();
76	        if (title == null || title.isBlank()) {
77	            return lastName;
