85	     */
86	    default String initials(Owner owner) {
87	        if (owner == null) {
88	            return null;
89	        }
90	        StringBuilder sb = new StringBuilder();
91	        String firstName = owner.getFirstName();
92	        String lastName = owner.getLastName();
93	        if (firstName != null && !firstName.isEmpty()) {
94	            sb.append(Character.toUpperCase(firstName.charAt(0))).append('.');
95	        }
96	        if (lastName != null && !lastName.isEmpty()) {
97	            sb.append(Character.toUpperCase(lastName.charAt(0))).append('.');
98	        }
99	        return sb.toString();
