142	    /**
143	     * Derives the owner's user-facing locality (region) directly from the owner's postcode, using
144	     * the shared {@link Regions#forPostcode(String)} table. This is the plain region code (e.g.
145	     * {@code NSW}); it is deliberately <em>not</em> read back from the {@code memberId}, whose region
146	     * component now carries the version-2 tag. Returns {@link Regions#UNKNOWN} when the postcode is
147	     * absent or in no known region.
148	     */
149	    default String locality(Owner owner) {
150	        if (owner == null) {
151	            return null;
152	        }
153	        return Regions.forPostcode(owner.getPostcode());
154	    }
155	
156	    /**
157	     * Derives the owner's IANA {@code timezone} from its locality/region using the fixed
158	     * region-to-timezone table ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
159	     * {@code QLD -> Australia/Brisbane}). Returns {@code null} when the region is not in the table.
160	     */
161	    default String timezone(Owner owner) {
162	        if (owner == null) {
163	            return null;
164	        }
165	        String region = locality(owner);
166	        return switch (region) {
167	            case "NSW" -> "Australia/Sydney";
168	            case "VIC" -> "Australia/Melbourne";
169	            case "QLD" -> "Australia/Brisbane";
170	            default -> null;
171	        };
172	    }
