174	    /**
175	     * Whether the owner carries the bulk-signup warning (more than 80 owners already created
176	     * on its registration day at creation time). A {@code null} stored value is treated as
177	     * {@code false}, so the field is always present in the response.
178	     */
179	    default Boolean bulkSignupWarning(Owner owner) {
180	        if (owner == null) {
181	            return null;
182	        }
183	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
184	    }
185	
186	    /**
187	     * Whether the owner carries the capacity warning (its city already held between 40 and 49
188	     * owners, approaching the capacity limit of 50, at creation time). A {@code null} stored value
189	     * is treated as {@code false}, so the field is always present in the response.
190	     */
191	    default Boolean capacityWarning(Owner owner) {
192	        if (owner == null) {
193	            return null;
194	        }
195	        return Boolean.TRUE.equals(owner.getCapacityWarning());
196	    }
197	
198	    /**
199	     * Whether the owner was flagged as a possible (soft) duplicate at creation time — not a hard
200	     * duplicate, but sharing an existing owner's last-name Soundex code and postcode while differing
201	     * on the identity key (typically a different telephone). A {@code null} stored value is treated
202	     * as {@code false}, so the field is always present in the response.
203	     */
204	    default Boolean possibleDuplicate(Owner owner) {
205	        if (owner == null) {
206	            return null;
207	        }
208	        return Boolean.TRUE.equals(owner.getPossibleDuplicate());
209	    }
210	
211	    /**
212	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
213	     * present, otherwise {@code PHONE}.
214	     */
215	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
216	        if (owner == null) {
217	            return null;
218	        }
219	        String email = owner.getEmail();
220	        return (email != null && !email.isEmpty())
221	            ? OwnerDto.ContactPreferenceEnum.EMAIL
222	            : OwnerDto.ContactPreferenceEnum.PHONE;
223	    }
224	
225	    /**
226	     * The owner-identity contract version surfaced as the response's {@code apiVersion}; always
227	     * {@link IdentityVersion#API_VERSION 2}.
228	     */
229	    default Integer apiVersion() {
230	        return IdentityVersion.API_VERSION;
231	    }
232	
233	    /**
234	     * Groups the owner's version-2 identifiers under the nested {@code identity} object: the stored
235	     * {@code memberId} and {@code householdId}, and the derived {@code identityKey} (the SHA-256 hex
236	     * over {@code versionTag + '|' + normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)};
237	     * see {@link IdentityKeyNormalizer}). Each identifier is rederived with the version-2 algorithm,
238	     * so no value produced under version 1 is produced again.
239	     */
240	    default OwnerIdentityDto identity(Owner owner) {
241	        if (owner == null) {
242	            return null;
243	        }
244	        OwnerIdentityDto identity = new OwnerIdentityDto();
245	        identity.setMemberId(owner.getMemberId());
246	        identity.setHouseholdId(owner.getHouseholdId());
247	        identity.setIdentityKey(IdentityKeyNormalizer.derive(owner));
248	        return identity;
249	    }
250	
251	    /**
252	     * Derives the owner's {@code ageBand} from {@code birthDate}, measured as of the owner's
253	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} when 18 to 64, and
254	     * {@code SENIOR} when 65 or older. Returns {@code null} when no birth date is known (or when
255	     * no reference registration date is available), so the field is absent from the response.
256	     */
257	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
258	        if (owner == null || owner.getBirthDate() == null) {
259	            return null;
260	        }
261	        LocalDate reference = owner.getRegistrationDate();
262	        if (reference == null) {
263	            reference = LocalDate.now();
264	        }
265	        int age = Period.between(owner.getBirthDate(), reference).getYears();
266	        if (age < 18) {
267	            return OwnerDto.AgeBandEnum.MINOR;
268	        }
269	        if (age < 65) {
270	            return OwnerDto.AgeBandEnum.ADULT;
271	        }
272	        return OwnerDto.AgeBandEnum.SENIOR;
273	    }
274	
275	    /**
276	     * Derives the owner's {@code selfLink}, the canonical API path for the owner, formed as
277	     * {@code '/api/owners/'} followed by the owner's id. Returns {@code null} until the owner
278	     * has an id, so the field is absent from the response.
279	     */
280	    default String selfLink(Owner owner) {
281	        if (owner == null || owner.getId() == null) {
282	            return null;
283	        }
284	        return "/api/owners/" + owner.getId();
285	    }
286	
287	    /**
288	     * Derives the owner's {@code ownerSegment}, formatted {@code '<TIER>_<AREA>'}. TIER is
289	     * {@code PREMIUM} when {@link #membershipLevel(Owner)} is 3 or more, otherwise {@code STANDARD}.
290	     * AREA is {@code METRO} when {@link #locality(Owner)} is a known region (NSW, VIC or QLD),
291	     * otherwise {@code REGIONAL}.
292	     */
293	    default OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
294	        if (owner == null) {
295	            return null;
296	        }
297	        Integer level = membershipLevel(owner);
298	        String tier = (level != null && level >= 3) ? "PREMIUM" : "STANDARD";
299	        String region = locality(owner);
300	        boolean metro = "NSW".equals(region) || "VIC".equals(region) || "QLD".equals(region);
301	        String area = metro ? "METRO" : "REGIONAL";
302	        return OwnerDto.OwnerSegmentEnum.fromValue(tier + "_" + area);
303	    }
304	
305	    /**
306	     * Whether the owner should be flagged for manual review. True when any one of these holds: the
307	     * owner is a possible (soft) duplicate ({@link #possibleDuplicate(Owner)}), the owner's e-mail
308	     * domain is disposable-adjacent ({@link EmailNormalizer#isDisposableAdjacent(String)}), or the
309	     * owner's city is over its soft capacity ({@link #capacityWarning(Owner)}). Otherwise false.
310	     * The result composes those three sub-flags rather than reading a stored value, so it is always
311	     * non-null (and thus always present in the response) for a non-null owner.
312	     */
313	    default Boolean riskFlag(Owner owner) {
314	        if (owner == null) {
315	            return null;
316	        }
317	        return Boolean.TRUE.equals(possibleDuplicate(owner))
318	            || EmailNormalizer.isDisposableAdjacent(owner.getEmail())
319	            || Boolean.TRUE.equals(capacityWarning(owner));
320	    }
321	
322	    @Mapping(target = "id", ignore = true)
323	    @Mapping(target = "pets", ignore = true)
324	    Owner toOwner(OwnerFieldsDto ownerDto);
325	
326	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
327	
328	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
329	
330	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
331	        OwnerPageDto ownerPageDto = new OwnerPageDto();
332	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
333	        ownerPageDto.setPage(ownerPage.getNumber());
334	        ownerPageDto.setSize(ownerPage.getSize());
335	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
336	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
337	        return ownerPageDto;
338	    }
339	}
