494	        String region = IdentityVersion.regionCode(Regions.forPostcode(owner.getPostcode()));
495	        LocalDate registrationDate = owner.getRegistrationDate() != null
496	            ? owner.getRegistrationDate() : LocalDate.now();
497	        String fiscalYear = RegistrationDateNormalizer.fiscalYearYY(registrationDate);
498	        String telephone = TelephoneNormalizer.toComparable(owner.getTelephone());
499	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
500	        String base = region + fiscalYear + sha256Hex8(IdentityVersion.TAG + telephone + lastName);
