504	    /**
505	     * Computes a single Luhn check digit (0-9) over the digits contained in {@code value};
506	     * non-digit characters are ignored.
507	     */
508	    private static int luhnCheckDigit(String value) {
509	        int sum = 0;
510	        boolean dbl = true;
511	        for (int i = value.length() - 1; i >= 0; i--) {
512	            char c = value.charAt(i);
513	            if (c < '0' || c > '9') {
514	                continue;
515	            }
516	            int d = c - '0';
517	            if (dbl) {
518	                d *= 2;
519	                if (d > 9) {
520	                    d -= 9;
521	                }
522	            }
523	            sum += d;
524	            dbl = !dbl;
525	        }
526	        return (10 - (sum % 10)) % 10;
527	    }
