529	    /**
530	     * De-duplicates a computed {@code memberId} against the existing owners: if no owner already
531	     * carries {@code baseId} it is returned unchanged, otherwise {@code '-<n>'} is appended with the
532	     * smallest {@code n} of 2 or more that yields a value no existing owner holds. Evaluated before the
533	     * owner is persisted, so it reflects the owners present at creation time.
534	     */
535	    private String deduplicateMemberId(String baseId) {
536	        Set<String> existingIds = findActiveOwners().stream()
537	            .map(Owner::getMemberId)
538	            .filter(Objects::nonNull)
539	            .collect(Collectors.toSet());
540	        if (!existingIds.contains(baseId)) {
541	            return baseId;
542	        }
543	        int n = 2;
544	        while (existingIds.contains(baseId + "-" + n)) {
545	            n++;
546	        }
547	        return baseId + "-" + n;
548	    }
