551	     * Returns the first eight upper-case hexadecimal characters (the first four bytes) of the
552	     * SHA-256 digest of the UTF-8 bytes of {@code value}.
553	     */
554	    private static String sha256Hex8(String value) {
555	        return sha256HexPrefix(value, 8).toUpperCase();
556	    }
