558	    /**
559	     * Returns the first {@code hexChars} lower-case hexadecimal characters of the SHA-256 digest of
560	     * the UTF-8 bytes of {@code value}.
561	     */
562	    private static String sha256HexPrefix(String value, int hexChars) {
563	        try {
564	            byte[] digest = MessageDigest.getInstance("SHA-256")
565	                .digest(value.getBytes(StandardCharsets.UTF_8));
566	            StringBuilder sb = new StringBuilder(hexChars);
567	            for (int i = 0; sb.length() < hexChars; i++) {
568	                sb.append(String.format("%02x", digest[i]));
569	            }
570	            return sb.substring(0, hexChars);
571	        }
572	        catch (NoSuchAlgorithmException e) {
573	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
574	        }
575	    }
