22	
23	/**
24	 * The membership-scoring business rules for an {@link Owner}. Kept as a standalone domain helper so
25	 * both the service (when capping a new owner's level against their household) and the presentation
26	 * mapper (when exposing the derived fields) share one definition rather than duplicating the ladder.
27	 */
28	public final class MembershipLevels {
29	
30	    private MembershipLevels() {
31	    }
32	
33	    /**
34	     * The owner's membership points. Starts at {@code 0}; adds {@code 2} when an email address is
35	     * present; adds {@code 1} when the owner has no namesakes (namesakeCount is 0); adds {@code 2}
36	     * when the owner belongs to a household of {@code 3} or more members; adds {@code 3} when the
37	     * owner's tenure exceeds one fiscal year, where tenure is the number of elapsed fiscal years
38	     * (the current fiscal year minus the registration fiscal year).
39	     */
40	    public static Integer points(Owner owner) {
41	        if (owner == null) {
42	            return null;
43	        }
44	        int points = 0;
45	        String email = owner.getEmail();
46	        if (email != null && !email.isEmpty()) {
47	            points += 2;
48	        }
49	        Integer namesakeCount = owner.getNamesakeCount();
50	        if (namesakeCount != null && namesakeCount == 0) {
51	            points += 1;
52	        }
53	        Integer householdMemberCount = owner.getHouseholdMemberCount();
54	        if (householdMemberCount != null && householdMemberCount >= 3) {
55	            points += 2;
56	        }
57	        LocalDate registrationDate = owner.getRegistrationDate();
58	        if (registrationDate != null) {
59	            int tenure = RegistrationDateNormalizer.fiscalYear(LocalDate.now())
60	                - RegistrationDateNormalizer.fiscalYear(registrationDate);
61	            if (tenure > 1) {
62	                points += 3;
63	            }
64	        }
65	        return points;
66	    }
67	
68	    /**
69	     * The owner's numeric membership level derived from {@link #points(Owner)}: level {@code 1} for
70	     * {@code 0-1} points, level {@code 2} for {@code 2-3} points, level {@code 3} for {@code 4-5}
71	     * points, and level {@code 4} for {@code 6} or more points. The result is then capped so it
72	     * cannot exceed the owner's {@code membershipLevelCap} (one above the maximum membership level
73	     * among the household members present when the owner was created); a {@code null} cap — set when
74	     * the owner had no existing household member — leaves the level uncapped.
75	     */
76	    public static Integer level(Owner owner) {
77	        if (owner == null) {
78	            return null;
79	        }
80	        int points = points(owner);
81	        int level;
82	        if (points <= 1) {
83	            level = 1;
84	        } else if (points <= 3) {
85	            level = 2;
86	        } else if (points <= 5) {
87	            level = 3;
88	        } else {
89	            level = 4;
90	        }
91	        Integer cap = owner.getMembershipLevelCap();
92	        if (cap != null && level > cap) {
93	            level = cap;
94	        }
95	        return level;
96	    }
97	}
