31	
32	    /**
33	     * Pragmatic syntactic check for an e-mail address: a non-empty local part, a single
34	     * {@code @}, and a dotted domain whose top-level label is alphabetic.
35	     */
36	    private static final Pattern EMAIL_PATTERN =
37	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
38	
39	    /**
40	     * Domains of disposable / throwaway e-mail providers that are not accepted for an owner.
41	     */
42	    private static final Set<String> DISPOSABLE_DOMAINS =
43	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
44	
45	    private EmailNormalizer() {
46	    }
47	
48	    /**
49	     * Normalize the supplied e-mail address.
50	     *
51	     * @param email the raw e-mail value (may be {@code null} because the field is optional)
52	     * @return {@code null} when the input is {@code null}, otherwise the address lower-cased
53	     * @throws InvalidEmailException if a value is supplied but is not syntactically valid,
54	     *     or its domain is on the disposable-domain blocklist
55	     */
56	    public static String normalize(String email) {
57	        if (email == null) {
58	            return null;
59	        }
60	        if (!EMAIL_PATTERN.matcher(email).matches()) {
61	            throw new InvalidEmailException("email must be a syntactically valid address");
62	        }
63	        String normalized = email.toLowerCase();
64	        String domain = normalized.substring(normalized.indexOf('@') + 1);
65	        if (DISPOSABLE_DOMAINS.contains(domain)) {
66	            throw new InvalidEmailException("email domain is not accepted");
67	        }
68	        return normalized;
69	    }
70	
71	    /**
72	     * Whether the supplied e-mail address is <em>disposable-adjacent</em>: a soft signal that its
73	     * domain resembles a known throwaway provider without necessarily being on the outright
74	     * {@link #DISPOSABLE_DOMAINS blocklist} (blocklisted domains are already rejected at create
75	     * time by {@link #normalize(String)}). A domain qualifies when it is, or is a subdomain of, a
76	     * blocklisted disposable domain (e.g. {@code mail.mailinator.com}), or when it shares the
77	     * registrable second-level label of one but uses a different top-level domain (e.g.
78	     * {@code mailinator.net} for the blocklisted {@code mailinator.com}).
79	     *
80	     * <p>Unlike {@link #normalize(String)} this never throws; a {@code null}, blank or
81	     * domain-less value is simply not adjacent.
82	     *
83	     * @param email the raw or stored e-mail value (may be {@code null})
84	     * @return {@code true} when the address's domain is disposable-adjacent
85	     */
86	    public static boolean isDisposableAdjacent(String email) {
87	        if (email == null) {
88	            return false;
89	        }
90	        int at = email.indexOf('@');
91	        if (at < 0 || at == email.length() - 1) {
92	            return false;
93	        }
94	        String domain = email.substring(at + 1).toLowerCase();
95	        for (String disposable : DISPOSABLE_DOMAINS) {
96	            if (domain.equals(disposable) || domain.endsWith("." + disposable)) {
97	                return true;
98	            }
99	        }
100	        String secondLevel = registrableLabel(domain);
101	        if (secondLevel == null) {
102	            return false;
103	        }
104	        for (String disposable : DISPOSABLE_DOMAINS) {
105	            if (secondLevel.equals(registrableLabel(disposable))) {
106	                return true;
107	            }
108	        }
109	        return false;
110	    }
111	
112	    /**
113	     * The registrable second-level label of a domain — the dot-separated label immediately before
114	     * the final (top-level) label, e.g. {@code mailinator} for both {@code mailinator.com} and
115	     * {@code mail.mailinator.com}. Returns {@code null} when the domain has no such label.
116	     */
117	    private static String registrableLabel(String domain) {
118	        String[] labels = domain.split("\\.");
119	        if (labels.length < 2) {
120	            return null;
121	        }
122	        return labels[labels.length - 2];
123	    }
124	}
