17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.util.Map;
20	
21	/**
22	 * Validates the optional postcode submitted when creating an owner. The postcode is validated
23	 * only <em>when present</em>: a {@code null} postcode is left untouched (an owner created without
24	 * a postcode stays valid). When present it must be a 4-digit value and, when the owner's city
25	 * maps to a known region, must fall within that region's fixed inclusive range
26	 * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
27	 * region accepts any 4-digit postcode.
28	 *
29	 * <p>An invalid postcode raises an {@link InvalidPostcodeException} so the request is rejected
30	 * with {@code 400 Bad Request}.
31	 */
32	public final class PostcodeValidator {
33	
34	    /** Fixed city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). */
35	    private static final Map<String, String> CITY_REGION = Map.of(
36	        "Sydney", "NSW",
37	        "Melbourne", "VIC",
38	        "Brisbane", "QLD");
39	
40	    private PostcodeValidator() {
41	    }
42	
43	    /**
44	     * Validate the supplied postcode for the given city.
45	     *
46	     * @param postcode the raw postcode value (may be {@code null} when absent)
47	     * @param city the owner's city, used to derive the region whose range applies
48	     * @throws InvalidPostcodeException if the postcode is present but not a 4-digit value, or is
49	     *                                  out of range for the city's region
50	     */
51	    public static void validate(String postcode, String city) {
52	        if (postcode == null) {
53	            return;
54	        }
55	        if (!postcode.matches("\\d{4}")) {
56	            throw new InvalidPostcodeException("postcode must be a 4-digit value");
57	        }
58	        String region = city == null ? null : CITY_REGION.get(city);
59	        int[] range = region == null ? null : Regions.REGION_POSTCODES.get(region);
60	        if (range != null) {
61	            int value = Integer.parseInt(postcode);
62	            if (value < range[0] || value > range[1]) {
63	                throw new InvalidPostcodeException(
64	                    "postcode " + postcode + " is not valid for region " + region);
65	            }
66	        }
67	    }
68	}
