18	
19	import java.util.Map;
20	import java.util.Optional;
21	import java.util.concurrent.ConcurrentHashMap;
22	
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Remembers the owner created for a given {@code Idempotency-Key}, so that a create
27	 * request that repeats with an already-seen key can return the originally created owner
28	 * instead of creating a duplicate. Keys are only recorded once the original create has
29	 * succeeded, so a failed attempt does not "burn" a key.
30	 */
31	@Component
32	public class IdempotencyStore {
33	
34	    private final Map<String, Integer> ownerIdsByKey = new ConcurrentHashMap<>();
35	
36	    /** The id of the owner previously created for {@code key}, if any. */
37	    public Optional<Integer> find(String key) {
38	        if (key == null || key.isBlank()) {
39	            return Optional.empty();
40	        }
41	        return Optional.ofNullable(ownerIdsByKey.get(key));
42	    }
43	
44	    /** Record the owner created for {@code key}. No-op when the key is blank. */
45	    public void remember(String key, Integer ownerId) {
46	        if (key != null && !key.isBlank() && ownerId != null) {
47	            ownerIdsByKey.putIfAbsent(key, ownerId);
48	        }
49	    }
50	}
