18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.Set;
22	
23	/**
24	 * Utility for normalizing an owner's registration date to a business day. The effective
25	 * registration date must never fall on a weekend or a public holiday, so a Saturday, Sunday
26	 * or listed public holiday is rolled forward to the next non-holiday business day; a weekday
27	 * value that is not a holiday is left untouched. This applies to the effective date whether
28	 * it was supplied in the request or defaulted to the server date, and any value derived from
29	 * the registration date (such as the membership number's year segment) uses the adjusted date.
30	 */
31	public final class RegistrationDateNormalizer {
32	
33	    /** Fixed list of public holidays that the registration date must roll past. */
34	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
35	        LocalDate.of(2026, 1, 1),
36	        LocalDate.of(2026, 1, 26),
37	        LocalDate.of(2026, 4, 25),
38	        LocalDate.of(2026, 12, 25),
39	        LocalDate.of(2026, 12, 28));
40	
41	    /** First month of the fiscal year (1 July). */
42	    private static final int FISCAL_YEAR_START_MONTH = 7;
43	
44	    private RegistrationDateNormalizer() {
45	    }
46	
47	    /**
48	     * Normalize the supplied registration date to a business day.
49	     *
50	     * @param date the effective registration date (must not be {@code null})
51	     * @return the same date when it falls on a non-holiday weekday, otherwise the next
52	     *         non-holiday business day
53	     */
54	    public static LocalDate normalize(LocalDate date) {
55	        LocalDate normalized = date;
56	        while (isWeekend(normalized) || PUBLIC_HOLIDAYS.contains(normalized)) {
57	            normalized = normalized.plusDays(1);
58	        }
59	        return normalized;
60	    }
61	
62	    private static boolean isWeekend(LocalDate date) {
63	        DayOfWeek dayOfWeek = date.getDayOfWeek();
64	        return dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY;
65	    }
66	
67	    /**
68	     * Determine the fiscal year that the supplied date falls in. The fiscal year starts on
69	     * 1 July, so a date on or after 1 July belongs to the fiscal year of the following calendar
70	     * year (e.g. 2025-07-01 through 2026-06-30 is fiscal year 2026), while a date before 1 July
71	     * belongs to the fiscal year of its own calendar year.
72	     *
73	     * @param date the (already business-day-adjusted) registration date
74	     * @return the four-digit fiscal year
75	     */
76	    public static int fiscalYear(LocalDate date) {
77	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
78	    }
79	
80	    /**
81	     * Format the last two digits (zero-padded) of the fiscal year that the supplied
82	     * (already business-day-adjusted) {@code date} falls in, e.g. fiscal year 2026 yields
83	     * {@code "26"}. Shared by every caller that renders the two-digit fiscal-year segment.
84	     *
85	     * @param date the (already business-day-adjusted) registration date
86	     * @return the two-digit, zero-padded fiscal year
87	     */
88	    public static String fiscalYearYY(LocalDate date) {
89	        return String.format("%02d", fiscalYear(date) % 100);
90	    }
91	}
