17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.util.Locale;
23	
24	import org.springframework.samples.petclinic.model.Owner;
25	
26	/**
27	 * Utility for deriving an owner's {@code identityKey}, the single value into which all
28	 * duplicate detection is consolidated. The key is the lower-case hexadecimal SHA-256 digest of
29	 * {@code versionTag + '|' + normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}: the
30	 * fixed {@link IdentityVersion#TAG version-2 tag}, the owner's telephone in
31	 * {@link TelephoneNormalizer E.164} form, the lower-cased e-mail address (or an empty string when
32	 * absent), and the {@link Soundex Soundex} code of the last name. Mixing in the version tag ensures
33	 * no key produced under version 1 is produced again.
34	 *
35	 * <p>Because the telephone is part of the key, two owners with the same last name and postcode but
36	 * different telephones have different identity keys; only an exact whole-key match between a new
37	 * owner and an existing one is a hard duplicate. Owners that merely share the last name's Soundex
38	 * code and postcode are surfaced as a soft match instead.
39	 */
40	public final class IdentityKeyNormalizer {
41	
42	    private IdentityKeyNormalizer() {
43	    }
44	
45	    /**
46	     * Derive the owner's identity key.
47	     *
48	     * @param owner the owner (may be {@code null})
49	     * @return the derived identity key, or {@code null} when the owner is {@code null}
50	     */
51	    public static String derive(Owner owner) {
52	        if (owner == null) {
53	            return null;
54	        }
55	        String telephone = TelephoneNormalizer.toComparable(owner.getTelephone());
56	        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase(Locale.ROOT);
57	        String soundex = Soundex.encode(owner.getLastName());
58	        return sha256Hex(IdentityVersion.TAG + "|" + telephone + "|" + email + "|" + soundex);
59	    }
60	
61	    /**
62	     * Returns the full lower-case hexadecimal SHA-256 digest of the UTF-8 bytes of {@code value}.
63	     */
64	    private static String sha256Hex(String value) {
65	        try {
66	            byte[] digest = MessageDigest.getInstance("SHA-256")
67	                .digest(value.getBytes(StandardCharsets.UTF_8));
68	            StringBuilder sb = new StringBuilder(digest.length * 2);
69	            for (byte b : digest) {
70	                sb.append(String.format("%02x", b));
71	            }
72	            return sb.toString();
73	        }
74	        catch (NoSuchAlgorithmException e) {
75	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
76	        }
77	    }
78	}
