19	/**
20	 * Utility computing the standard American Soundex code of a name: the retained (upper-cased)
21	 * first letter followed by up to three digits derived from the remaining consonants, zero-padded
22	 * to a four-character code. Two names that sound alike therefore share a code, which is how the
23	 * owner {@code identityKey} and the soft-duplicate rule group owners by last name.
24	 *
25	 * <p>Non-letters are ignored, vowels (and {@code y}) separate otherwise-adjacent equal codes, and
26	 * {@code h}/{@code w} are transparent (they do not separate). A {@code null} or letter-free value
27	 * encodes to an empty string.
28	 */
29	public final class Soundex {
30	
31	    private Soundex() {
32	    }
33	
34	    /**
35	     * Encode the supplied name as its four-character Soundex code.
36	     *
37	     * @param name the raw name (may be {@code null})
38	     * @return the Soundex code, or an empty string when {@code name} is {@code null} or has no letters
39	     */
40	    public static String encode(String name) {
41	        if (name == null) {
42	            return "";
43	        }
44	        StringBuilder letters = new StringBuilder();
45	        for (int i = 0; i < name.length(); i++) {
46	            char c = name.charAt(i);
47	            if (Character.isLetter(c)) {
48	                letters.append(Character.toUpperCase(c));
49	            }
50	        }
51	        if (letters.length() == 0) {
52	            return "";
53	        }
54	        char first = letters.charAt(0);
55	        StringBuilder code = new StringBuilder().append(first);
56	        char prev = codeOf(first);
57	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
58	            char c = letters.charAt(i);
59	            if (c == 'H' || c == 'W') {
60	                // Transparent: two same-coded letters split by H/W stay a single code.
61	                continue;
62	            }
63	            char digit = codeOf(c);
64	            if (digit != '0' && digit != prev) {
65	                code.append(digit);
66	            }
67	            // A vowel (or Y) resets the running code so a repeat after it is coded again.
68	            prev = isVowel(c) ? '0' : digit;
69	        }
70	        while (code.length() < 4) {
71	            code.append('0');
72	        }
73	        return code.substring(0, 4);
74	    }
75	
76	    private static boolean isVowel(char c) {
77	        return c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U' || c == 'Y';
78	    }
79	
80	    private static char codeOf(char c) {
81	        return switch (c) {
82	            case 'B', 'F', 'P', 'V' -> '1';
83	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
84	            case 'D', 'T' -> '3';
85	            case 'L' -> '4';
86	            case 'M', 'N' -> '5';
87	            case 'R' -> '6';
88	            default -> '0';
89	        };
90	    }
91	}
